def find_sum(arr):
    """
    Given a list of numbers, find the sum of all the numbers that are divisible by 3 and belong to the range of 1 to n.

    Args:
    arr (list): A list of positive integers

    Returns:
    int: Sum of numbers divisible by 3 and are in the range of 1 to n
    """

### Solution:


    try:
        n = int(input("Enter a positive integer: "))

        if n <= 0:
            print("Invalid input! Please enter a positive integer.")
            return

        num_sum = 0

        for i in range(1, n+1):
            try:
                if i % 3 == 0:
                    num_sum += arr[i-1]
            except IndexError:
                print("Index out of range! Skipping the current number.")
                continue

        return num_sum

    except ValueError:
        print("Invalid input! Please enter a positive integer.")

