### Problem:
def xor_intersection(sets):
    """
    This function computes the intersection of sets using XOR operator.

    Args:
    sets (list): A list of sets.

    Returns:
    set: The intersection of sets.

    Raises:
    ValueError: If sets is empty or contains sets with different types.
    """

### Solution:


    if not sets:
        raise ValueError("Sets list cannot be empty.")

    set_types = {type(s) for s in sets}
    if len(set_types) > 1:
        raise ValueError("Sets must all have the same type.")

    result = set()
    result_count = 0

    for s in sets:
        if result_count == 0:
            result = s
            result_count += 1
        else:
            result ^= s
            result_count += 1

    return result


